import { Outlet, Link } from "react-router-dom";
import { Navigation } from "./navigation"; // Import the PrimeReact Navigation
import { PanelMenu } from "primereact/panelmenu";
import "../components/css/VetLayout.css"; // Ensure CSS is imported

const VetLayout = () => {
  const menuItems = [
    {
      label: "Dashboard",
      icon: "pi pi-home",
      command: () => (window.location.href = "/clinic/dashboard"),
    },
    {
      label: "Appointments",
      icon: "pi pi-calendar",
      command: () => (window.location.href = "/clinic/appointments"),
    },
    {
      label: "History",
      icon: "pi pi-history",
      command: () => (window.location.href = "/clinic/history"),
    },
  ];

  return (
    <div>

      <div className="vet-container flex">
        {/* Sidebar */}
        <div className="sidebar2 p-3">
          <h2 className="text-lg font-bold mb-3">Clinic Panel</h2>
          <PanelMenu model={menuItems} className="w-full" />
        </div>

        {/* Content */}
        <main className="vet-content flex-1 p-4">
          <Outlet />
        </main>
      </div>
    </div>
  );
};

export default VetLayout;
